def compute(vars):
    global_headquarters_lease = vars["v1"]
    total_contractual_obligations = vars["v2"]

    if total_contractual_obligations == 0:
        return None

    ratio = global_headquarters_lease / total_contractual_obligations
    percentage = ratio * 100

    return {
        "value": percentage,
        "trace": {
            "v1": global_headquarters_lease,
            "v2": total_contractual_obligations,
            "ratio": ratio,
            "percentage": percentage,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
